-- Animation as data. Keys are {time, value, easing?}; `in_out` shapes the segment arriving at
-- the key. Values offset the rest pose: x/y in drawing units, rot in degrees about the pivot.
return {
  -- Breathing: the body bobs, the head lags a little, the arms sway.
  idle = {
    length = 1.2, loop = true,
    tracks = {
      body = { y = { {0, 0}, {0.6, -3, "in_out"}, {1.2, 0, "in_out"} } },
      head = { rot = { {0, 0}, {0.6, 3, "in_out"}, {1.2, 0, "in_out"} } },
      arm_near = { rot = { {0, 0}, {0.6, -6, "in_out"}, {1.2, 0, "in_out"} } },
      arm_far = { rot = { {0, 0}, {0.6, 6, "in_out"}, {1.2, 0, "in_out"} } },
    },
  },
  -- Walking in place: legs and arms swing in opposition, the body dips on each step. The
  -- world moves the hero; this only has to look like walking.
  walk = {
    length = 0.5, loop = true,
    tracks = {
      leg_l = { rot = { {0, 22}, {0.25, -22, "in_out"}, {0.5, 22, "in_out"} } },
      leg_r = { rot = { {0, -22}, {0.25, 22, "in_out"}, {0.5, -22, "in_out"} } },
      arm_near = { rot = { {0, -18}, {0.25, 18, "in_out"}, {0.5, -18, "in_out"} } },
      arm_far = { rot = { {0, 18}, {0.25, -18, "in_out"}, {0.5, 18, "in_out"} } },
      body = { y = {
        {0, 0}, {0.125, -3, "in_out"}, {0.25, 0, "in_out"},
        {0.375, -3, "in_out"}, {0.5, 0, "in_out"},
      } },
    },
  },
  -- Walking in profile: legs stride forward and back about the hip, arms counter-swing.
  walk_side = {
    length = 0.5, loop = true,
    tracks = {
      leg_l = { rot = { {0, 28}, {0.25, -28, "in_out"}, {0.5, 28, "in_out"} } },
      leg_r = { rot = { {0, -28}, {0.25, 28, "in_out"}, {0.5, -28, "in_out"} } },
      arm_near = { rot = { {0, 24}, {0.25, -24, "in_out"}, {0.5, 24, "in_out"} } },
      arm_far = { rot = { {0, -24}, {0.25, 24, "in_out"}, {0.5, -24, "in_out"} } },
      body = { y = {
        {0, 0}, {0.125, -3, "in_out"}, {0.25, 0, "in_out"},
        {0.375, -3, "in_out"}, {0.5, 0, "in_out"},
      } },
    },
  },
  -- A jump, played once: the body — and everything hanging off it — rises and falls while the
  -- entity's feet stay where they are, so draw order ignores the jump. Legs tuck, arms lift.
  jump = {
    length = 0.45,
    tracks = {
      body = { y = {
        {0, 0}, {0.1, -28}, {0.225, -40, "in_out"}, {0.35, -28, "in_out"}, {0.45, 0},
      } },
      leg_l = { y = { {0, 0}, {0.225, -10, "in_out"}, {0.45, 0, "in_out"} } },
      leg_r = { y = { {0, 0}, {0.225, -10, "in_out"}, {0.45, 0, "in_out"} } },
      arm_near = { rot = { {0, 0}, {0.225, -30, "in_out"}, {0.45, 0, "in_out"} } },
      arm_far = { rot = { {0, 0}, {0.225, 30, "in_out"}, {0.45, 0, "in_out"} } },
    },
  },
  -- Holding something in front: both arms turn in toward the middle, the body breathes.
  carry = {
    length = 1.2, loop = true,
    tracks = {
      body = { y = { {0, 0}, {0.6, -2, "in_out"}, {1.2, 0, "in_out"} } },
      arm_near = { rot = { {0, 35} } },
      arm_far = { rot = { {0, -35} } },
    },
  },
  -- Walking while holding: the walk's legs and bob, the carry's arms. One clip plays at a time
  -- (no layers yet), so the two are combined here by hand.
  carry_walk = {
    length = 0.5, loop = true,
    tracks = {
      leg_l = { rot = { {0, 22}, {0.25, -22, "in_out"}, {0.5, 22, "in_out"} } },
      leg_r = { rot = { {0, -22}, {0.25, 22, "in_out"}, {0.5, -22, "in_out"} } },
      arm_near = { rot = { {0, 35} } },
      arm_far = { rot = { {0, -35} } },
      body = { y = {
        {0, 0}, {0.125, -3, "in_out"}, {0.25, 0, "in_out"},
        {0.375, -3, "in_out"}, {0.5, 0, "in_out"},
      } },
    },
  },
  -- The lid swings back about its hinge and holds there.
  open = { length = 0.5, tracks = { lid = { rot = { {0, 0}, {0.5, -100, "in_out"} } } } },
  close = { length = 0.4, tracks = { lid = { rot = { {0, -100}, {0.4, 0, "in_out"} } } } },
}

-- The lid hinges at its back edge, so an "open" clip is one rotation about that pivot.
return {
  size = { 96, 80 },
  parts = {
    { id = "base", pivot = { 48, 80 }, shapes = {
      { path = { {"move",8,36}, {"line",88,36}, {"line",88,76}, {"quad",88,80,84,80},
        {"line",12,80}, {"quad",8,80,8,76}, {"close"} },
        fill = "#9a5b2e", stroke = { 2.5, "#2b1a10" } },
      { path = { {"move",8,50}, {"line",88,50}, {"line",88,56}, {"line",8,56}, {"close"} },
        fill = "#e0b04a" },
    } },
    { id = "lid", parent = "base", pivot = { 8, 36 }, shapes = {
      { path = { {"move",8,36}, {"line",8,24}, {"cubic",8,6,88,6,88,24}, {"line",88,36}, {"close"} },
        fill = "#b36a36", stroke = { 2.5, "#2b1a10" } },
      { path = { {"move",42,30}, {"line",54,30}, {"line",54,42}, {"line",42,42}, {"close"} },
        fill = "#e0b04a", stroke = { 2, "#2b1a10" } },
    } },
  },
  -- The lid swings back about its hinge and holds there.
  clips = {
    open = { length = 0.5, tracks = { lid = { rot = { {0, 0}, {0.5, -100, "in_out"} } } } },
    close = { length = 0.4, tracks = { lid = { rot = { {0, -100}, {0.4, 0, "in_out"} } } } },
  },
  -- Solid along its base; its sensor is the reach of whoever comes to open it.
  world = { collider = { rect = { 80, 24 }, at = { 8, 56 } }, sensor = { circle = 72, at = { 48, 68 } } },
}

-- A wooden crate. Loose by default: anything that walks into it pushes it.
local S = 48
return {
  size = { S, S },
  parts = {
    { id = "box", pivot = { S / 2, S / 2 }, shapes = {
      { path = { {"move",1,1}, {"line",S-1,1}, {"line",S-1,S-1}, {"line",1,S-1}, {"close"} },
        fill = "#a8743f", stroke = { 2.5, "#2b1a10" } },
      { path = { {"move",4,4}, {"line",S-4,S-4} }, stroke = { 3, "#6b4423" } },
      { path = { {"move",S-4,4}, {"line",4,S-4} }, stroke = { 3, "#6b4423" } },
    } },
  },
  world = { collider = { rect = { S, S } }, loose = true },
}

-- A stage: assets placed together. Positions are the top-left of each asset's box; a mounted
-- entity has no position of its own — it sits on its host's socket. An entity's world fields
-- (`collider`, `sensor`, `loose`, `group`, `blocks`) replace its asset's `world` ones; `false`
-- takes one away. `controller` is the room's alone.
return {
  scene = {
    size = { 720, 400 },
    entities = {
      { id = "chest", asset = "chest", pos = { 460, 264 } },
      -- The room's keys drive this hero; the rival, the same asset, has none.
      { id = "hero", asset = "hero", pos = { 140, 110 }, clip = "idle", controller = {
        speed = 160, axis_x = { neg = "KeyA", pos = "KeyD" }, axis_y = { neg = "KeyW", pos = "KeyS" },
      } },
      { id = "crate", asset = "crate", pos = { 40, 308 } },
      -- On the floor: drag its brim onto the hero's head and it equips onto `head_top`.
      { id = "hat", asset = "hat", pos = { 320, 300 } },
      -- The same hero asset in a teal shirt: an entity's `vars` make a variant of its asset.
      { id = "rival", asset = "hero", pos = { 560, 100 }, clip = "idle",
        vars = { shirt = "#2ec4b6", shirt_shade = "#25a89c", shirt_far = "#1f8f85" } },
    },
  },
}

workspace_custom.code:
return {
  bg = "#10141d",
  panel = "#1a2130",
  hover = "#232e42",
  line = "#34415a",
  text = "#edf2ff",
  muted = "#9baac4",
  accent = "#83adff",
  kinds = {
    app = "#83adff", doc = "#86dbb1",
    table = "#eac280", canvas = "#c5a1f2",
  },
}

local C = require("theme")
local cursor = require("cursor")
local editor = require("editor")

local function card(item)
  local accent = C.kinds[item.kind] or C.accent
  return ui.col({
    id = "launcher:item:" .. item.id,
    w = 200, min_w = 180, h = 144, pad = 18, gap = 12,
    radius = 14, fill = C.panel, stroke = { 1, C.line },
    hover_fill = C.hover, hover_stroke = { 1, accent },
    tint = 140, press_scale = 0.97, cursor = "arrow",
    on_click = function() shell.open_item(item.id) end,
    ui.row({
      gap = 8, align_center = true,
      ui.col({ w = 8, h = 8, radius = 4, fill = accent }),
      ui.text({ string.upper(item.kind), color = accent, font_size = 11, no_wrap = true }),
    }),
    ui.text({ item.name, color = C.text, font_size = 19 }),
    ui.col({ grow = true }),
    ui.text({ "Open app →", color = C.muted, font_size = 12, no_wrap = true }),
  })
end

return function()
  local snapshot = shell.snapshot()
  local cards = {}
  for _, item in ipairs(snapshot.items) do
    cards[#cards + 1] = card(item)
  end
  return ui.col({
    id = "launcher:root", grow = true, stretch = true,
    fill = C.bg, radius = 18, pad = 20, gap = 16,
    on_hover = cursor.track, system_cursor = false,
    ui.row({
      id = "launcher:workspace-header", wrap = true, gap = 12, align_center = true,
      ui.button({
        id = "launcher:back", h = 36, px = 10, center = true, no_shrink = true,
        radius = 6, hover_fill = C.hover, tint = 120,
        on_click = function() shell.back() end,
        ui.text({ "← Back", color = C.muted, font_size = 13, no_wrap = true }),
      }),
      ui.text({ snapshot.workspace.name, grow = true, min_w = 60, color = C.text, font_size = 15 }),
      ui.button({
        id = "launcher:add-item", h = 36, px = 14, center = true, no_shrink = true,
        radius = 6, fill = C.accent, press_scale = 0.97,
        on_click = function() shell.import_item() end,
        ui.text({ "+ Add item", color = C.bg, font_size = 13, no_wrap = true }),
      }),
    }),
    ui.row({
      wrap = true, gap = 12, align_center = true,
      ui.text({ "Your apps", color = C.text, font_size = 24, no_wrap = true }),
      ui.col({ grow = true }), editor.button(),
    }),
    ui.text({ "A workspace made yours", color = C.muted, font_size = 13 }),
    #cards == 0 and ui.col({
      grow = true, center = true,
      ui.text({ "no apps in this workspace yet", color = C.muted, font_size = 13 }),
    }) or ui.col({
      id = "launcher:items", grow = true, scroll_y = true,
      ui.row({ wrap = true, gap = 16, cards }),
    }),
    editor.view(),
    cursor.view(),
  })
end
